def _more(courses, more):
    """Adds MORE (or a dict like it) to the scenes (see the note above MORE)."""
    for c in courses:
        for u in c['units']:
            for les in u['lessons']:
                scenes = {sc['id']: sc for sc in les['scenes']}
                for sid, by_level in more.get(les['id'], {}).items():
                    sc = scenes[sid]
                    for lv in sorted(by_level):
                        add = by_level[lv]
                        pos, lines = add if isinstance(add, tuple) else (None, add)
                        if lv not in sc['levels']:  # a new level for this scene: these lines are its own narration
                            sc['levels'] = sorted(sc['levels'] + [lv])
                            sc['say'][lv] = list(lines)
                            continue
                        owner = lambda t: max((x for x in sc['say'] if x <= t and sc['say'][x]), default=None)
                        src = owner(lv)
                        base = {t: list(sc['say'][src]) for t in c['levels']
                                if t >= lv and t in sc['levels'] and owner(t) == src}
                        for t, cur in base.items():
                            if pos is None:
                                cur += lines
                            else:
                                cur[pos:pos] = lines
                            sc['say'][t] = cur


